parameters.text:
=Clasifica el siguiente email de soporte y redacta el borrador de respuesta.

### INICIO_EMAIL_ENTRANTE ###
De: {{ ($json.From ?? $json.from ?? '').toString() }}
Asunto: {{ ($json.Subject ?? $json.subject ?? '').toString() }}
Cuerpo:
{{ ($json.text ?? $json.textPlain ?? $json.snippet ?? '').toString().slice(0, 4000) }}
### FIN_EMAIL_ENTRANTE ###

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "categoria": {
      "type": "string",
      "enum": [
        "facturacion",
        "envio",
        "devolucion",
        "producto",
        "tecnico",
        "otro"
      ]
    },
    "prioridad": {
      "type": "string",
      "enum": [
        "alta",
        "media",
        "baja"
      ]
    },
    "resumen": {
      "type": "string",
      "description": "Una linea con el problema del cliente"
    },
    "respuesta_sugerida": {
      "type": "string",
      "description": "Borrador completo de respuesta"
    },
    "requiere_humano": {
      "type": "boolean"
    }
  },
  "required": [
    "categoria",
    "prioridad",
    "resumen",
    "respuesta_sugerida",
    "requiere_humano"
  ]
}
